<?php
require_once __DIR__.'/auth.php';require_once __DIR__.'/db.php';require_once __DIR__.'/historical_report_helper.php';require_once __DIR__.'/application_requirements_helper.php';require_once __DIR__.'/document_submission_helper.php';require_once __DIR__.'/spes_lifecycle_helper.php';
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: private, no-store');
if(!auth_first_active_role(['admin','peso_staff'])){http_response_code(403);echo json_encode(['error'=>'Your session expired.']);exit;}
if($_SERVER['REQUEST_METHOD']!=='GET'){http_response_code(405);exit;}
$program=trim((string)($_GET['program_name']??''));if($program===''){http_response_code(422);echo json_encode(['error'=>'Select a program first.']);exit;}
$where=['p.program_name=?','NOT '.historical_record_condition()];$params=[$program];$types='s';
foreach(['program_id'=>'b.program_id','barangay'=>'b.barangay','approval'=>'b.approval_status','availment'=>'b.availment_status'] as $key=>$column){$value=trim((string)($_GET[$key]??''));if($value===''||$value==='All'||($key==='program_id'&&(int)$value<=0))continue;$where[]=$column.'=?';$params[]=$value;$types.='s';}
$search=trim((string)($_GET['search']??''));if($search!==''){$where[]='(b.full_name LIKE ? OR b.email LIKE ? OR b.first_name LIKE ? OR b.last_name LIKE ?)';for($i=0;$i<4;$i++){$params[]='%'.$search.'%';$types.='s';}}
if(in_array($_GET['requirements_review']??'',['followup','issues'],true))$where[]=application_requirements_issue_sql($conn);
$reason=($_GET['requirements_review']??'')==='followup' ? trim((string)($_GET['resubmission_reason_filter']??'')) : '';if(in_array($reason,document_resubmission_reasons(),true)){if(document_submission_reason_available($conn)){$where[]="EXISTS (SELECT 1 FROM application_document_submissions ds WHERE ds.beneficiary_id=b.beneficiary_id AND ds.requested_at IS NOT NULL AND (CASE WHEN ds.resubmission_reason IN ('Incomplete Document','Unreadable Document','Incorrect Information','Expired Document') THEN 'Invalid Document' ELSE ds.resubmission_reason END)=?)";$params[]=$reason;$types.='s';}else $where[]='1=0';}

$category=trim((string)($_GET['tupad_category']??'All'));if(stripos($program,'TUPAD')!==false&&$category!=='All'){$where[]="COALESCE(NULLIF(TRIM(p.tupad_category),''),'Regular TUPAD')=?";$params[]=$category;$types.='s';}
$nature=trim((string)($_GET['business_nature']??'All'));if(stripos($program,'MSME')!==false&&$nature!=='All'){$where[]="FIND_IN_SET(?,REPLACE(REPLACE(REPLACE(b.business_nature,';',','),', ',','),' ,',','))>0";$params[]=$nature;$types.='s';}
try{$s=$conn->prepare('SELECT b.beneficiary_id,b.full_name,b.availment_status FROM beneficiaries b JOIN programs p ON p.program_id=b.program_id WHERE '.implode(' AND ',$where).' ORDER BY b.beneficiary_id LIMIT 501');$s->bind_param($types,...$params);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();if(count($rows)>500){http_response_code(422);echo json_encode(['error'=>'More than 500 records match. Narrow the filters before selecting all.']);exit;}echo json_encode(['rows'=>$rows,'count'=>count($rows)]);}catch(Throwable $e){error_log('Application selection: '.$e->getMessage());http_response_code(503);echo json_encode(['error'=>'Matching beneficiaries could not be loaded. Please try again.']);}
